//! Integration tests for `clipcheck_engine::import`.
//!
//! Planning tests need no media. Copy tests use real tiny mp4 files generated by
//! `clipcheck-testkit` and skip (see common/mod.rs) when it is unavailable.

#[macro_use]
mod common;

use clipcheck_testkit::MediaSpec;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant, UNIX_EPOCH};

use clipcheck_engine::catalog::{probe_media, MediaInfo};
use clipcheck_engine::import::{
    disk_free_bytes, plan_import, run_import, ImportItem, ImportPlan, ImportProgress, ImportReport,
    ImportRequest, SkipReason, CLIPS_FOLDER, FREE_SPACE_MARGIN, IMPORTED_GAME, NOT_A_VIDEO,
};

const MIB: usize = 1024 * 1024;
/// Fixed source modified time used by the copy tests, Unix seconds.
const T1: u64 = 1_600_000_000;

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

fn write_file(path: &Path, bytes: &[u8]) {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("create dir");
    }
    fs::write(path, bytes).expect("write file");
}

fn set_mtime_secs(path: &Path, secs: u64) {
    fs::OpenOptions::new()
        .write(true)
        .open(path)
        .expect("open for mtime")
        .set_modified(UNIX_EPOCH + Duration::from_secs(secs))
        .expect("set mtime");
}

/// Writes a video-only `secs`-long 160x120 10 fps test clip (H.264, faststart mp4).
fn make_clip(out: &Path, secs: u32) {
    if let Some(parent) = out.parent() {
        fs::create_dir_all(parent).expect("create dir");
    }
    let spec = MediaSpec::h264_aac(f64::from(secs))
        .with_video(160, 120, 10)
        .with_audio(Vec::new());
    clipcheck_testkit::write_mp4(out, &spec).expect("testkit could not write test clip");
}

fn req(sources: Vec<PathBuf>, game: Option<&str>, dest_root: &Path) -> ImportRequest {
    ImportRequest {
        sources,
        game: game.map(str::to_string),
        dest_root: dest_root.to_path_buf(),
        copy: true,
    }
}

/// Plans with plenty of free space and no library entries.
fn plan_of(r: &ImportRequest) -> ImportPlan {
    plan_import(r, |_| Ok(u64::MAX / 2), |_, _, _| false)
}

/// Plans with a fixed free-space answer. `None` makes the query fail.
fn plan_with_free(r: &ImportRequest, free: Option<u64>) -> ImportPlan {
    plan_import(
        r,
        move |_| free.ok_or_else(|| io::Error::other("no volume")),
        |_, _, _| false,
    )
}

fn file_name(p: &Path) -> String {
    p.file_name().unwrap().to_string_lossy().into_owned()
}

fn item<'a>(plan: &'a ImportPlan, name: &str) -> &'a ImportItem {
    plan.items
        .iter()
        .find(|i| file_name(&i.src) == name)
        .unwrap_or_else(|| panic!("no plan item named {name}"))
}

fn all_files(root: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    let mut stack = vec![root.to_path_buf()];
    while let Some(dir) = stack.pop() {
        for entry in fs::read_dir(&dir).expect("read_dir").flatten() {
            let path = entry.path();
            if entry.file_type().expect("file type").is_dir() {
                stack.push(path);
            } else {
                out.push(path);
            }
        }
    }
    out
}

fn assert_no_part(root: &Path) {
    if !root.exists() {
        return;
    }
    for f in all_files(root) {
        assert!(
            !file_name(&f).ends_with(".part"),
            "leftover part file {}",
            f.display()
        );
    }
}

struct Run {
    report: ImportReport,
    /// (dest, game, mtime_ms) for every call to `register`.
    calls: Vec<(PathBuf, String, i64)>,
}

/// Runs a plan with the real probe. `register_error` makes `register` fail.
fn run_plan(plan: &ImportPlan, register_error: Option<&str>) -> Run {
    let cancel = AtomicBool::new(false);
    let probe = probe_media;
    let mut calls = Vec::new();
    let mut count = 0u32;
    let mut register = |dest: &Path, game: &str, _info: &MediaInfo, mtime: i64| {
        calls.push((dest.to_path_buf(), game.to_string(), mtime));
        if let Some(e) = register_error {
            return Err(e.to_string());
        }
        count += 1;
        Ok(format!("id-{count}"))
    };
    let mut progress = |_: &ImportProgress| {};
    let report = run_import(plan, &probe, &mut register, &mut progress, &cancel);
    Run { report, calls }
}

