// planning (no tools needed)
// ---------------------------------------------------------------------------

#[test]
fn plan_walks_recursively_and_ignores_junk() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("Game/keep.mp4"), b"abc");
    write_file(&src.join("Game/deep/nested/deeper.MKV"), b"abcd");
    write_file(&src.join("Game/empty.mp4"), b"");
    write_file(&src.join("$RECYCLE.BIN/x.mp4"), b"junk");
    write_file(&src.join("Game/$R1ABC.mp4"), b"junk");
    write_file(&src.join("Game/$I2XYZ.mp4"), b"junk");
    write_file(&src.join("Game/$rlower.mp4"), b"junk");
    write_file(&src.join("Thumbnails/t.mp4"), b"junk");
    write_file(&src.join("Temp/tmp.mp4"), b"junk");
    write_file(&src.join("Game/Tempo.mp4"), b"kept");

    let plan = plan_of(&req(vec![src.clone()], None, &dest));
    let mut names: Vec<String> = plan.items.iter().map(|i| file_name(&i.src)).collect();
    names.sort();
    assert_eq!(names, ["Tempo.mp4", "deeper.MKV", "keep.mp4"]);

    let keep = item(&plan, "keep.mp4");
    assert_eq!(keep.size, 3);
    assert!(keep.mtime_ms > 0, "mtime not recorded");
    assert_eq!(keep.skip_reason, None);
}

#[test]
fn plan_lists_unsupported_with_lowercase_extension() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("G/a.txt"), b"x");
    write_file(&src.join("G/b.JPG"), b"x");
    write_file(&src.join("G/c.mp4"), b"x");
    write_file(&src.join("G/d.MP4"), b"x");
    write_file(&src.join("G/e.MOV"), b"x");

    let plan = plan_of(&req(vec![src], None, &dest));
    assert_eq!(
        item(&plan, "a.txt").skip_reason,
        Some(SkipReason::Unsupported("txt".into()))
    );
    assert_eq!(
        item(&plan, "b.JPG").skip_reason,
        Some(SkipReason::Unsupported("jpg".into()))
    );
    assert_eq!(item(&plan, "c.mp4").skip_reason, None);
    let upper = item(&plan, "d.MP4");
    assert_eq!(upper.skip_reason, None, ".MP4 must be supported");
    assert_eq!(upper.dest.file_name().unwrap(), "d.MP4", "name case kept");
    assert_eq!(item(&plan, "e.MOV").skip_reason, None);
}

#[test]
fn plan_derives_game_from_parent_folder() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("Old/Elden Ring/a.mp4"), b"x");
    write_file(&src.join("Downloads/b.mp4"), b"x");
    write_file(&src.join("Clips/d.mp4"), b"x");
    write_file(&src.join("Imports/e.mp4"), b"x");
    write_file(&src.join("Documents/f.mp4"), b"x");

    let plan = plan_of(&req(vec![src], None, &dest));
    let a = item(&plan, "a.mp4");
    assert_eq!(a.game, "Elden Ring");
    assert_eq!(
        a.dest,
        dest.join(CLIPS_FOLDER).join("Elden Ring").join("a.mp4")
    );
    for generic in ["b.mp4", "d.mp4", "e.mp4", "f.mp4"] {
        assert_eq!(item(&plan, generic).game, IMPORTED_GAME, "{generic}");
    }
}

#[test]
fn plan_forced_game_overrides_folder_and_blank_is_ignored() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("Old/Elden Ring/a.mp4"), b"x");
    write_file(&src.join("Other/b.mp4"), b"x");

    let forced = plan_of(&req(vec![src.clone()], Some("Forced Name"), &dest));
    assert!(forced.items.iter().all(|i| i.game == "Forced Name"));
    assert!(forced.items.iter().all(|i| i
        .dest
        .starts_with(dest.join(CLIPS_FOLDER).join("Forced Name"))));

    let colon = plan_of(&req(vec![src.clone()], Some("A:B"), &dest));
    assert!(
        colon.items.iter().all(|i| i.game == "AB"),
        "A:B must sanitize to AB"
    );

    let blank = plan_of(&req(vec![src], Some("   "), &dest));
    assert_eq!(item_game(&blank, "a.mp4"), "Elden Ring");
    assert_eq!(item_game(&blank, "b.mp4"), "Other");
}

fn item_game(plan: &ImportPlan, name: &str) -> String {
    item(plan, name).game.clone()
}

#[test]
fn plan_same_name_in_one_import_gets_numbered_destinations() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("a/x.mp4"), b"123");
    write_file(&src.join("b/x.mp4"), b"1234");
    write_file(&src.join("c/x.mp4"), b"12345");

    let plan = plan_of(&req(vec![src], Some("G"), &dest));
    assert!(plan.items.iter().all(|i| i.skip_reason.is_none()));
    let mut names: Vec<String> = plan.items.iter().map(|i| file_name(&i.dest)).collect();
    names.sort();
    assert_eq!(names, ["x (2).mp4", "x (3).mp4", "x.mp4"]);
    assert!(plan
        .items
        .iter()
        .all(|i| i.dest.parent() == Some(dest.join(CLIPS_FOLDER).join("G").as_path())));
}

#[test]
fn plan_marks_duplicate_inside_import() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("a/dup.mp4"), b"same bytes");
    write_file(&src.join("b/dup.mp4"), b"same bytes");
    set_mtime_secs(&src.join("a/dup.mp4"), T1);
    set_mtime_secs(&src.join("b/dup.mp4"), T1);

    let plan = plan_of(&req(vec![src], None, &dest));
    let dups = plan
        .items
        .iter()
        .filter(|i| i.skip_reason == Some(SkipReason::DuplicateInImport))
        .count();
    let kept = plan
        .items
        .iter()
        .filter(|i| i.skip_reason.is_none())
        .count();
    assert_eq!(dups, 1, "exactly one copy must be a duplicate");
    assert_eq!(kept, 1);
}

#[test]
fn plan_marks_already_in_library_by_destination_and_by_closure() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("Elden Ring/a.mp4"), b"AAAA");
    set_mtime_secs(&src.join("Elden Ring/a.mp4"), T1);
    write_file(
        &dest.join(CLIPS_FOLDER).join("Elden Ring").join("a.mp4"),
        b"AAAA",
    );
    set_mtime_secs(
        &dest.join(CLIPS_FOLDER).join("Elden Ring").join("a.mp4"),
        T1,
    );
    write_file(&src.join("Other/lib.mp4"), b"L");
    write_file(&src.join("Other/keep.mp4"), b"K");

    let r = req(vec![src], None, &dest);
    let plan = plan_import(
        &r,
        |_| Ok(u64::MAX / 2),
        |name: &str, _size: u64, _mtime: i64| name == "lib.mp4",
    );
    assert_eq!(
        item(&plan, "a.mp4").skip_reason,
        Some(SkipReason::AlreadyInLibrary)
    );
    assert_eq!(
        item(&plan, "lib.mp4").skip_reason,
        Some(SkipReason::AlreadyInLibrary)
    );
    assert_eq!(item(&plan, "keep.mp4").skip_reason, None);
}

#[test]
fn plan_same_name_different_size_at_destination_is_not_duplicate() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("Game/a.mp4"), b"abcdef");
    set_mtime_secs(&src.join("Game/a.mp4"), T1);
    write_file(&dest.join(CLIPS_FOLDER).join("Game").join("a.mp4"), b"zz");
    set_mtime_secs(&dest.join(CLIPS_FOLDER).join("Game").join("a.mp4"), T1);

    let plan = plan_of(&req(vec![src], None, &dest));
    let a = item(&plan, "a.mp4");
    assert_eq!(a.skip_reason, None);
    assert_eq!(file_name(&a.dest), "a (2).mp4");
}

#[test]
fn plan_free_space_boundaries() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    write_file(&src.join("Game/one.mp4"), &[1u8; 1000]);
    write_file(&src.join("Game/skip.txt"), &[1u8; 5000]);
    let r = req(vec![src], None, &dest);

    let total = plan_with_free(&r, Some(u64::MAX / 2)).total_bytes;
    assert_eq!(total, 1000, "unsupported bytes must not count");

    let exact = plan_with_free(&r, Some(total + FREE_SPACE_MARGIN));
    assert!(exact.enough_space, "exact margin must be enough");
    assert_eq!(exact.free_bytes, total + FREE_SPACE_MARGIN);
    assert_eq!(exact.total_bytes, total);

    let one_short = plan_with_free(&r, Some(total + FREE_SPACE_MARGIN - 1));
    assert!(!one_short.enough_space, "one byte short must not be enough");

    let zero = plan_with_free(&r, Some(0));
    assert!(!zero.enough_space);
    assert_eq!(zero.free_bytes, 0);

    let failed = plan_with_free(&r, None);
    assert_eq!(failed.free_bytes, 0);
    assert!(!failed.enough_space);
    assert_eq!(failed.total_bytes, total);
}

