#[test]
fn run_copies_two_files_from_two_folders() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    make_clip(&src.join("Alpha").join("a.mp4"), 1);
    make_clip(&src.join("Beta").join("b.mp4"), 2);

    let plan = plan_of(&req(vec![src.clone()], None, &dest));
    let run = run_plan(&plan, None);
    assert!(
        run.report.failed.is_empty(),
        "failed: {:?}",
        run.report.failed
    );
    assert_eq!(run.report.imported.len(), 2);

    for (name, game) in [("a.mp4", "Alpha"), ("b.mp4", "Beta")] {
        let d = dest.join(CLIPS_FOLDER).join(game).join(name);
        assert!(d.is_file(), "missing {}", d.display());
        let s = src.join(game).join(name);
        assert_eq!(
            fs::metadata(&d).unwrap().len(),
            fs::metadata(&s).unwrap().len(),
            "size differs for {name}"
        );
        assert!(
            run.calls.iter().any(|(p, g, _)| p == &d && g == game),
            "register not called for {} as {game}: {:?}",
            d.display(),
            run.calls
        );
    }
    assert_eq!(run.calls.len(), 2);
    let info = &run.report.imported[0].info;
    assert_eq!((info.width, info.height), (160, 120));
}

#[test]
fn run_preserves_modified_time() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    let clip = src.join("Game").join("old.mp4");
    make_clip(&clip, 1);
    set_mtime_secs(&clip, T1);

    let plan = plan_of(&req(vec![src], None, &dest));
    let run = run_plan(&plan, None);
    assert_eq!(
        run.report.imported.len(),
        1,
        "failed: {:?}",
        run.report.failed
    );
    assert_eq!(run.report.imported[0].mtime_ms, T1 as i64 * 1000);

    let d = dest.join(CLIPS_FOLDER).join("Game").join("old.mp4");
    let got = fs::metadata(&d).unwrap().modified().unwrap();
    let want = UNIX_EPOCH + Duration::from_secs(T1);
    let diff = match got.duration_since(want) {
        Ok(d) => d,
        Err(e) => e.duration(),
    };
    assert!(diff <= Duration::from_secs(2), "mtime off by {diff:?}");
}

#[test]
fn run_leaves_no_part_file_on_success() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    make_clip(&src.join("Game").join("a.mp4"), 1);

    let run = run_plan(&plan_of(&req(vec![src], None, &dest)), None);
    assert_eq!(
        run.report.imported.len(),
        1,
        "failed: {:?}",
        run.report.failed
    );
    assert!(dest.join(CLIPS_FOLDER).join("Game").join("a.mp4").is_file());
    assert_no_part(&dest);
}

#[test]
fn run_never_modifies_source() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    let clip = src.join("Game").join("a.mp4");
    make_clip(&clip, 1);
    set_mtime_secs(&clip, T1);
    let bytes_before = fs::read(&clip).unwrap();
    let mtime_before = fs::metadata(&clip).unwrap().modified().unwrap();

    let run = run_plan(&plan_of(&req(vec![src], None, &dest)), None);
    assert_eq!(
        run.report.imported.len(),
        1,
        "failed: {:?}",
        run.report.failed
    );

    assert_eq!(
        fs::read(&clip).unwrap(),
        bytes_before,
        "source bytes changed"
    );
    assert_eq!(
        fs::metadata(&clip).unwrap().modified().unwrap(),
        mtime_before,
        "source mtime changed"
    );
}

#[test]
fn run_invalid_file_fails_and_leaves_nothing() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    make_clip(&src.join("Good").join("good.mp4"), 1);
    write_file(&src.join("Bad").join("bad.mp4"), b"not a video");

    let plan = plan_of(&req(vec![src.clone()], None, &dest));
    let run = run_plan(&plan, None);
    assert_eq!(run.report.imported.len(), 1, "good file must still import");
    assert_eq!(
        run.report.failed.len(),
        1,
        "failed: {:?}",
        run.report.failed
    );
    let (failed_src, err) = &run.report.failed[0];
    assert_eq!(file_name(failed_src), "bad.mp4");
    assert_eq!(err, NOT_A_VIDEO);

    assert!(
        !dest.join(CLIPS_FOLDER).join("Bad").join("bad.mp4").exists(),
        "invalid copy was kept"
    );
    assert!(
        run.calls.iter().all(|(p, _, _)| file_name(p) != "bad.mp4"),
        "register called for invalid file"
    );
    assert_eq!(run.calls.len(), 1);
    assert!(src.join("Bad").join("bad.mp4").is_file(), "source removed");
    assert_no_part(&dest);
}

#[test]
fn run_register_error_removes_copy() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    make_clip(&src.join("Game").join("a.mp4"), 1);

    let plan = plan_of(&req(vec![src], None, &dest));
    let run = run_plan(&plan, Some("boom"));
    assert!(run.report.imported.is_empty());
    assert_eq!(
        run.report.failed.len(),
        1,
        "failed: {:?}",
        run.report.failed
    );
    assert!(
        run.report.failed[0].1.contains("boom"),
        "error text: {}",
        run.report.failed[0].1
    );
    assert_eq!(run.calls.len(), 1);
    assert!(
        !dest.join(CLIPS_FOLDER).join("Game").join("a.mp4").exists(),
        "copy kept after register failed"
    );
    assert_no_part(&dest);
}

#[test]
fn run_cancel_mid_copy_removes_partial_and_keeps_earlier_files() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    make_clip(&src.join("Small").join("s.mp4"), 1);
    let small_bytes = fs::metadata(src.join("Small").join("s.mp4")).unwrap().len();
    // Cancellation is driven by the unthrottled first progress call for big.mp4
    // (sent before any bytes are copied, made unthrottled by the sleep in register), so the size only needs
    // to be a few chunks.
    let big_size = 16 * MIB;
    write_file(&src.join("Big").join("big.mp4"), &vec![0u8; big_size]);

    let plan = plan_of(&req(
        vec![src.join("Small"), src.join("Big")],
        Some("Cancel Test"),
        &dest,
    ));
    assert_eq!(plan.items.len(), 2);

    let cancel = AtomicBool::new(false);
    let probe = probe_media;
    let mut registered = Vec::new();
    let mut register = |d: &Path, _g: &str, _i: &MediaInfo, _m: i64| {
        registered.push(d.to_path_buf());
        // Outlast the 100 ms progress throttle so the next file's first progress call
        // (sent before any bytes are copied) is delivered. Sleeping never returns early.
        std::thread::sleep(std::time::Duration::from_millis(250));
        Ok::<String, String>("id".to_string())
    };
    let mut progress = |p: &ImportProgress| {
        if p.current_name == "big.mp4" && p.bytes_done >= small_bytes {
            cancel.store(true, Ordering::SeqCst);
        }
    };
    let report = run_import(&plan, &probe, &mut register, &mut progress, &cancel);
    drop(register);

    assert!(report.cancelled, "run was not cancelled");
    assert_eq!(report.imported.len(), 1, "earlier file must be kept");
    assert!(report.failed.is_empty(), "failed: {:?}", report.failed);
    assert_eq!(registered.len(), 1);
    let game_dir = dest.join(CLIPS_FOLDER).join("Cancel Test");
    assert!(game_dir.join("s.mp4").is_file(), "completed file missing");
    assert!(!game_dir.join("big.mp4").exists(), "cancelled file kept");
    assert!(!game_dir.join("big.mp4.part").exists(), "partial copy kept");
    assert_no_part(&dest);
    assert_eq!(
        fs::metadata(src.join("Big").join("big.mp4")).unwrap().len(),
        big_size as u64,
        "source size changed"
    );
}

#[test]
fn second_plan_after_run_reports_already_in_library() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    make_clip(&src.join("Alpha").join("a.mp4"), 1);
    make_clip(&src.join("Beta").join("b.mp4"), 2);
    set_mtime_secs(&src.join("Alpha").join("a.mp4"), T1);
    set_mtime_secs(&src.join("Beta").join("b.mp4"), T1 + 60);

    let r = req(vec![src], None, &dest);
    let first = run_plan(&plan_of(&r), None);
    assert_eq!(
        first.report.imported.len(),
        2,
        "failed: {:?}",
        first.report.failed
    );

    let plan2 = plan_of(&r);
    assert_eq!(plan2.items.len(), 2);
    for it in &plan2.items {
        assert_eq!(
            it.skip_reason,
            Some(SkipReason::AlreadyInLibrary),
            "{}",
            it.src.display()
        );
    }
    let second = run_plan(&plan2, None);
    assert!(second.report.imported.is_empty());
    assert_eq!(second.report.skipped.len(), 2);
    assert!(second.calls.is_empty(), "register called for skipped files");
}

#[test]
fn run_progress_is_monotonic_and_throttled() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    make_clip(&src.join("A").join("a1.mp4"), 1);
    make_clip(&src.join("B").join("a2.mp4"), 2);
    write_file(&src.join("C").join("huge.mp4"), &vec![0u8; 64 * MIB]);

    let plan = plan_of(&req(vec![src], None, &dest));
    assert_eq!(plan.items.len(), 3);
    let file_count = plan.items.len();

    let cancel = AtomicBool::new(false);
    let probe = probe_media;
    let mut register = |_: &Path, _: &str, _: &MediaInfo, _: i64| Ok::<String, String>("id".into());
    let mut seen: Vec<ImportProgress> = Vec::new();
    let mut progress = |p: &ImportProgress| seen.push(p.clone());

    let started = Instant::now();
    let report = run_import(&plan, &probe, &mut register, &mut progress, &cancel);
    let elapsed = started.elapsed();

    assert_eq!(report.imported.len(), 2, "failed: {:?}", report.failed);
    assert_eq!(report.failed.len(), 1, "huge.mp4 should fail the probe");
    assert!(!seen.is_empty(), "no progress callbacks");

    for w in seen.windows(2) {
        assert!(
            w[1].bytes_done >= w[0].bytes_done,
            "bytes_done went backwards: {} -> {}",
            w[0].bytes_done,
            w[1].bytes_done
        );
    }
    let last = seen.last().unwrap();
    assert_eq!(last.file_count, file_count);
    assert_eq!(last.file_index, file_count, "last callback file_index");
    assert_eq!(
        last.bytes_done, last.bytes_total,
        "last callback not complete"
    );
    assert_eq!(last.bytes_total, plan.total_bytes);

    let limit = elapsed.as_millis() / 100 + 5;
    assert!(
        (seen.len() as u128) <= limit,
        "{} callbacks in {elapsed:?}, limit {limit}",
        seen.len()
    );
}

#[cfg(windows)]
#[test]
fn run_copies_to_destination_deeper_than_max_path() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    make_clip(&src.join("Long").join("long.mp4"), 1);

    let mut deep = t.path().join("deep");
    for i in 0..5 {
        deep = deep.join(format!("{}{i}", "d".repeat(55)));
    }
    let plan = plan_of(&req(vec![src], Some("Long"), &deep));
    let dest_len = plan.items[0].dest.as_os_str().len();
    assert!(dest_len > 300, "destination only {dest_len} chars");

    let run = run_plan(&plan, None);
    assert_eq!(
        run.report.imported.len(),
        1,
        "long-path import failed: {:?}",
        run.report.failed
    );
    let verbatim = PathBuf::from(format!(r"\\?\{}", plan.items[0].dest.display()));
    assert!(
        verbatim.is_file(),
        "copy not found at {}",
        verbatim.display()
    );
    assert_no_part(&deep);
}

#[test]
fn run_same_name_across_folders_gets_numbered_names() {
    tools_or_skip!();
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    // Different durations give different sizes, so these are not duplicates.
    make_clip(&src.join("One").join("x.mp4"), 1);
    make_clip(&src.join("Two").join("x.mp4"), 2);

    let plan = plan_of(&req(vec![src], Some("Same Game"), &dest));
    let run = run_plan(&plan, None);
    assert_eq!(
        run.report.imported.len(),
        2,
        "failed: {:?}",
        run.report.failed
    );

    let mut names: Vec<String> = run
        .report
        .imported
        .iter()
        .map(|f| file_name(&f.dest))
        .collect();
    names.sort();
    assert_eq!(names, ["x (2).mp4", "x.mp4"]);
    let game_dir = dest.join(CLIPS_FOLDER).join("Same Game");
    for n in &names {
        assert!(game_dir.join(n).is_file(), "missing {n}");
    }
}

#[test]
fn plan_accepts_mp4_m4v_mov_mkv_and_skips_webm() {
    let t = tempfile::tempdir().expect("tempdir");
    let src = t.path().join("src");
    let dest = t.path().join("dest");
    for name in ["a.mp4", "b.m4v", "c.mov", "d.mkv", "e.webm", "f.WEBM"] {
        write_file(&src.join("G").join(name), b"x");
    }

    let plan = plan_of(&req(vec![src], None, &dest));
    for name in ["a.mp4", "b.m4v", "c.mov", "d.mkv"] {
        assert_eq!(item(&plan, name).skip_reason, None, "{name} must be copied");
    }
    for name in ["e.webm", "f.WEBM"] {
        assert_eq!(
            item(&plan, name).skip_reason,
            Some(SkipReason::Unsupported("webm".into())),
            "{name} must be skipped as unsupported"
        );
    }
}
